 5	 * Immutable description of the matches found for a single search operation.
 6	 */
 7	public final class KmpMatchResult {
 8	    private static final KmpMatchResult NO_MATCHES = new KmpMatchResult(List.of());
 9	
10	    private final List<Integer> matchIndices;
