12	    private KmpMatchResult(List<Integer> matchIndices) {
13	        this.matchIndices = matchIndices;
14	    }
15	
16	    public static KmpMatchResult from(List<Integer> matchIndices) {
17	        if (matchIndices.isEmpty()) {
18	            return NO_MATCHES;
19	        }
20	
21	        return new KmpMatchResult(List.copyOf(matchIndices));
22	    }
23	
24	    public static KmpMatchResult noMatches() {
25	        return NO_MATCHES;
26	    }
27	
28	    public List<Integer> matchIndices() {
29	        return matchIndices;
30	    }
31	
