  9	    public static void main(String[] args) {
 10	        assertEquals(List.of(0, 9, 12), KmpSearch.search("aaba", "aabaacaadaabaaba"), "basic search");
 11	        assertEquals(List.of(0, 1, 2), KmpSearch.search("aa", "aaaa"), "overlapping matches");
 12	        assertEquals(List.of(), KmpSearch.search("xyz", "aaaa"), "no matches");
 13	        assertEquals(List.of(), KmpSearch.search("longer-pattern", "short"), "pattern longer than text");
 14	        assertAnalysis(KmpSearch.analyze("aaba", "aabaacaadaabaaba"), List.of(0, 9, 12), "analysis through facade");
 15	        assertEquals(OptionalInt.of(2), KmpSearch.findFirst("aaba", "xxaabaacaadaabaaba"), "first match through facade");
 16	        assertEquals(3, KmpSearch.countMatches("aa", "aaaa"), "count matches through facade");
 17	        assertTrue(KmpSearch.contains("aba", "xxabaxx"), "contains through facade");
 18	        assertFalse(KmpSearch.contains("aba", "xxxx"), "contains through facade negative");
 19	        assertEquals(List.of(0, 2), collectMatches("aba", "ababa"), "forEachMatch through facade");
 20	
 21	        KmpPattern compiledPattern = KmpPattern.compile("aba");
 22	        assertEquals("aba", compiledPattern.value(), "compiled pattern preserves source value");
 23	        assertAnalysis(compiledPattern.analyzeIn("ababa"), List.of(0, 2), "compiled pattern analysis");
 24	        assertEquals(List.of(0, 2), compiledPattern.findMatchesIn("ababa"), "compiled pattern search");
 25	        assertEquals(List.of(0, 2), compiledPattern.findMatchesIn(new StringBuilder("ababa")), "char sequence search");
 26	        assertEquals(OptionalInt.of(0), compiledPattern.findFirstIn("ababa"), "first match search");
 27	        assertEquals(OptionalInt.empty(), compiledPattern.findFirstIn("xxxx"), "first match no result");
 28	        assertEquals(2, compiledPattern.countMatchesIn("ababa"), "count matches");
 29	        assertTrue(compiledPattern.occursIn("xxabaxx"), "occursIn should detect matches");
 30	        assertFalse(compiledPattern.occursIn("xxxx"), "occursIn should reject missing matches");
 31	        assertEquals(List.of(0, 2), collectMatches(compiledPattern, "ababa"), "forEachMatchIn enumerates matches");
 32	        assertThrows(UnsupportedOperationException.class, () -> compiledPattern.findMatchesIn("ababa").add(99), "match list is immutable");
 33	
 34	        assertThrows(IllegalArgumentException.class, () -> KmpPattern.compile(""), "empty pattern rejected");
 35	        assertThrows(NullPointerException.class, () -> KmpPattern.compile(null), "null pattern rejected");
 36	        assertThrows(NullPointerException.class, () -> compiledPattern.findMatchesIn(null), "null text rejected");
 37	        assertThrows(NullPointerException.class, () -> compiledPattern.forEachMatchIn("ababa", null), "null match consumer rejected");
 38	    }
 39	
 40	    private static void assertAnalysis(KmpMatchResult result, List<Integer> expectedMatches, String scenario) {
 41	        assertEquals(expectedMatches, result.matchIndices(), scenario + " indices");
 42	        assertEquals(expectedMatches.size(), result.count(), scenario + " count");
 43	        assertEquals(!expectedMatches.isEmpty(), result.hasMatches(), scenario + " presence");
 44	        assertEquals(toOptional(expectedMatches.isEmpty() ? null : expectedMatches.get(0)), result.firstMatch(), scenario + " first");
 45	        assertEquals(
 46	                toOptional(expectedMatches.isEmpty() ? null : expectedMatches.get(expectedMatches.size() - 1)),
 47	                result.lastMatch(),
 48	                scenario + " last");
 49	        assertEquals(expectedMatches.toString(), result.toString(), scenario + " string");
 50	    }
 51	
 52	    private static List<Integer> collectMatches(KmpPattern pattern, CharSequence text) {
 53	        List<Integer> matches = new java.util.ArrayList<>();
 54	        pattern.forEachMatchIn(text, matches::add);
 55	        return List.copyOf(matches);
 56	    }
 57	
 58	    private static List<Integer> collectMatches(CharSequence pattern, CharSequence text) {
 59	        List<Integer> matches = new java.util.ArrayList<>();
 60	        KmpSearch.forEachMatch(pattern, text, matches::add);
 61	        return List.copyOf(matches);
 62	    }
 63	
 64	    private static OptionalInt toOptional(Integer value) {
 65	        return value == null ? OptionalInt.empty() : OptionalInt.of(value);
 66	    }
 67	
 68	    private static void assertEquals(Object expected, Object actual, String scenario) {
 69	        if (!expected.equals(actual)) {
 70	            throw new AssertionError(scenario + ": expected " + expected + " but got " + actual);
 71	        }
 72	    }
 73	
 74	    private static void assertTrue(boolean condition, String scenario) {
 75	        if (!condition) {
 76	            throw new AssertionError(scenario);
 77	        }
 78	    }
 79	
 80	    private static void assertFalse(boolean condition, String scenario) {
 81	        assertTrue(!condition, scenario);
 82	    }
 83	
 84	    private static void assertThrows(
 85	            Class<? extends Throwable> expectedType,
 86	            ThrowingRunnable action,
 87	            String scenario) {
 88	        try {
 89	            action.run();
 90	        } catch (Throwable thrown) {
 91	            if (expectedType.isInstance(thrown)) {
 92	                return;
 93	            }
 94	
 95	            throw new AssertionError(
 96	                    scenario + ": expected " + expectedType.getSimpleName()
 97	                            + " but got " + thrown.getClass().getSimpleName(),
 98	                    thrown);
 99	        }
100	
101	        throw new AssertionError(scenario + ": expected " + expectedType.getSimpleName());
102	    }
103	
104	    @FunctionalInterface
105	    private interface ThrowingRunnable {
106	        void run();
107	    }
108	}

