  7	/**
  8	 * Immutable compiled representation of a pattern for Knuth-Morris-Pratt searches.
  9	 */
 10	public final class KmpPattern {
 11	    private final String value;
 12	    private final int[] longestPrefixSuffix;
 13	
 14	    private KmpPattern(String value, int[] longestPrefixSuffix) {
 15	        this.value = value;
 16	        this.longestPrefixSuffix = longestPrefixSuffix;
 17	    }
 18	
 19	    public static KmpPattern compile(CharSequence pattern) {
 20	        Objects.requireNonNull(pattern, "pattern must not be null");
 21	
 22	        String patternValue = pattern.toString();
 23	
 24	        if (patternValue.isEmpty()) {
 25	            throw new IllegalArgumentException("pattern must not be empty");
 26	        }
 27	
 28	        return new KmpPattern(patternValue, buildLongestPrefixSuffixTable(patternValue));
 29	    }
 30	
 31	    public String value() {
 32	        return value;
 33	    }
 34	
 35	    public KmpMatchResult analyzeIn(CharSequence text) {
 36	        validateText(text);
 37	
 38	        if (value.length() > text.length()) {
 39	            return KmpMatchResult.noMatches();
 40	        }
 41	
 42	        List<Integer> matches = new ArrayList<>();
 43	        scanMatches(text, matchIndex -> {
 44	            matches.add(matchIndex);
 45	            return true;
 46	        });
 47	        return KmpMatchResult.from(matches);
 48	    }
 49	
 50	    public List<Integer> findMatchesIn(CharSequence text) {
 51	        return analyzeIn(text).matchIndices();
 52	    }
 53	
 54	    public OptionalInt findFirstIn(CharSequence text) {
 55	        validateText(text);
 56	
 57	        if (value.length() > text.length()) {
 58	            return OptionalInt.empty();
 59	        }
 60	
 61	        int[] firstMatchIndex = { -1 };
 62	        scanMatches(text, matchIndex -> {
 63	            firstMatchIndex[0] = matchIndex;
 64	            return false;
 65	        });
 66	        return firstMatchIndex[0] >= 0 ? OptionalInt.of(firstMatchIndex[0]) : OptionalInt.empty();
 67	    }
 68	
 69	    public int countMatchesIn(CharSequence text) {
 70	        validateText(text);
 71	
 72	        if (value.length() > text.length()) {
 73	            return 0;
 74	        }
 75	
 76	        int[] matchCount = { 0 };
 77	        scanMatches(text, matchIndex -> {
 78	            matchCount[0]++;
 79	            return true;
 80	        });
 81	        return matchCount[0];
 82	    }
 83	
 84	    public boolean occursIn(CharSequence text) {
 85	        return findFirstIn(text).isPresent();
 86	    }
 87	
 88	    public void forEachMatchIn(CharSequence text, IntConsumer matchConsumer) {
 89	        validateText(text);
 90	        Objects.requireNonNull(matchConsumer, "matchConsumer must not be null");
 91	
 92	        if (value.length() > text.length()) {
 93	            return;
 94	        }
 95	
 96	        scanMatches(text, matchIndex -> {
 97	            matchConsumer.accept(matchIndex);
 98	            return true;
 99	        });
100	    }
101	
102	    static int[] buildLongestPrefixSuffixTable(String pattern) {
103	        int[] table = new int[pattern.length()];
104	        int prefixLength = 0;
105	        int currentIndex = 1;
106	
107	        while (currentIndex < pattern.length()) {
108	            if (pattern.charAt(currentIndex) == pattern.charAt(prefixLength)) {
109	                table[currentIndex] = ++prefixLength;
110	                currentIndex++;
111	                continue;
112	            }
113	
114	            if (prefixLength > 0) {
115	                prefixLength = table[prefixLength - 1];
116	            } else {
117	                table[currentIndex] = 0;
118	                currentIndex++;
119	            }
120	        }
121	
122	        return table;
123	    }
124	
125	    private void validateText(CharSequence text) {
126	        Objects.requireNonNull(text, "text must not be null");
127	    }
128	
129	    private void scanMatches(CharSequence text, MatchVisitor visitor) {
130	        int textIndex = 0;
131	        int patternIndex = 0;
132	
133	        while (textIndex < text.length()) {
134	            if (text.charAt(textIndex) == value.charAt(patternIndex)) {
135	                textIndex++;
136	                patternIndex++;
137	
138	                if (patternIndex == value.length()) {
139	                    int matchIndex = textIndex - patternIndex;
140	                    patternIndex = longestPrefixSuffix[patternIndex - 1];
141	
142	                    if (!visitor.visit(matchIndex)) {
143	                        return;
144	                    }
145	                }
146	                continue;
147	            }
148	
149	            if (patternIndex > 0) {
150	                patternIndex = longestPrefixSuffix[patternIndex - 1];
151	            } else {
152	                textIndex++;
153	            }
154	        }
155	    }
156	
157	    @FunctionalInterface
158	    private interface MatchVisitor {
159	        boolean visit(int matchIndex);
160	    }
161	}

