 4	/**
 5	 * One-shot iterator over zero-based KMP match indices for a specific text input.
 6	 */
 7	public final class KmpMatchIterator implements PrimitiveIterator.OfInt {
 8	    private final String pattern;
 9	    private final int[] longestPrefixSuffix;
10	    private final CharSequence text;
11	
12	    private int textIndex;
13	    private int patternIndex;
14	    private int nextMatchIndex;
15	    private boolean nextMatchReady;
16	    private boolean exhausted;
17	
18	    KmpMatchIterator(String pattern, int[] longestPrefixSuffix, CharSequence text) {
19	        this.pattern = pattern;
20	        this.longestPrefixSuffix = longestPrefixSuffix;
21	        this.text = text;
22	        this.exhausted = pattern.length() > text.length();
23	    }
24	
25	    @Override
26	    public boolean hasNext() {
27	        if (nextMatchReady) {
28	            return true;
29	        }
30	
31	        if (exhausted) {
32	            return false;
33	        }
34	
35	        while (textIndex < text.length()) {
36	            if (text.charAt(textIndex) == pattern.charAt(patternIndex)) {
37	                textIndex++;
38	                patternIndex++;
39	
40	                if (patternIndex == pattern.length()) {
41	                    nextMatchIndex = textIndex - patternIndex;
42	                    patternIndex = longestPrefixSuffix[patternIndex - 1];
43	                    nextMatchReady = true;
44	                    return true;
45	                }
46	                continue;
47	            }
48	
49	            if (patternIndex > 0) {
50	                patternIndex = longestPrefixSuffix[patternIndex - 1];
51	            } else {
52	                textIndex++;
53	            }
54	        }
55	
56	        exhausted = true;
57	        return false;
58	    }
59	
60	    @Override
61	    public int nextInt() {
62	        if (!hasNext()) {
63	            throw new NoSuchElementException("No remaining matches");
64	        }
65	
66	        nextMatchReady = false;
67	        return nextMatchIndex;
68	    }
69	}

