 1	public final class KmpSearchDemo {
 2	    private static final String DEFAULT_TEXT = "aabaacaadaabaaba";
 3	    private static final String DEFAULT_PATTERN = "aaba";
 4	
 5	    private KmpSearchDemo() {
 6	    }
 7	
 8	    public static void main(String[] args) {
 9	        String text = args.length > 0 ? args[0] : DEFAULT_TEXT;
10	        String pattern = args.length > 1 ? args[1] : DEFAULT_PATTERN;
11	
12	        KmpPattern compiledPattern = KmpSearch.compile(pattern);
13	        KmpMatchResult result = compiledPattern.analyzeIn(text);
14	        KmpMatchIterator iterator = compiledPattern.matchIteratorIn(text);
15	
16	        System.out.println("Matches: " + result.matchIndices());
17	        System.out.println("Count: " + result.count());
18	        System.out.println("First: " + formatOptional(result.firstMatch()));
19	        System.out.println("Last: " + formatOptional(result.lastMatch()));
20	        System.out.println("Contains: " + result.hasMatches());
21	
22	        System.out.print("Iterated: ");
23	        while (iterator.hasNext()) {
24	            int matchIndex = iterator.nextInt();
25	            System.out.print(matchIndex + " ");
26	        }
27	        if (!result.hasMatches()) {
28	            System.out.print("none");
29	        }
30	        System.out.println();
31	    }
